import{_ as a,a0 as p,w as d,s as n,ao as r,I as o,x as t,a1 as i,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"怎樣在 Linux 命令列下殺死一個進程 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Linux 命令列下殺死一個進程 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Linux 命令列下殺死一個進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Linux 命令列下殺死一個進程 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170519 How to Kill a Process from the Command Line","title":"怎樣在 Linux 命令列下殺死一個進程","tag":"201705","desc":""},"relativePath":"201705/20170519 How to Kill a Process from the Command Line.md","filePath":"[post].md"}'),c={name:"201705/20170519 How to Kill a Process from the Command Line.md"};function h(m,e,u,k,g,f){const l=p("Link");return d(),n("div",null,[e[13]||(e[13]=r(`<h1 id="怎樣在-linux-命令列下殺死一個進程" tabindex="-1">怎樣在 Linux 命令列下殺死一個進程 <a class="header-anchor" href="#怎樣在-linux-命令列下殺死一個進程" aria-label="Permalink to “怎樣在 Linux 命令列下殺死一個進程”">​</a></h1><blockquote><p>Linux 的命令列裏面有用來停止正在運行的進程的所有所需工具。Jack Wallen 將為您講述細節。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/stop-processes.jpg?itok=vfNx8VRz" alt="stop processes" title="stop processes"></p><p>想像一下：你打開了一個程序（可能來自於你的桌面菜單或者命令列），然後開始使用這個程序，沒想到程序會鎖死、停止運行、或者意外死機。你嘗試再次運行該程序，但是它反饋説原來的進程沒有完全關閉。</p><p>你該怎麼辦？你要結束進程。但該如何做？不管你信與不信，最好的解決方法大都在命令列裏。值得慶幸的是， Linux 有供用户殺死錯誤的進程的每個必要的工具，然而，你在執行殺死進程的命令之前，你首先需要知道進程是什麼。該如何處理這一類的任務。一旦你能夠掌握這種工具，它實際是十分簡單的……</p><p>讓我來介紹給你這些工具。</p><p>我來概述的步驟是每個 Linux 發行版都能用的，不論是桌面版還是服務器版。我將限定只使用命令列，請打開你的終端開始輸入命令吧。</p><h3 id="定位進程" tabindex="-1">定位進程 <a class="header-anchor" href="#定位進程" aria-label="Permalink to “定位進程”">​</a></h3><p>殺死一個沒有響應的進程的第一個步驟是定位這個進程。我用來定位進程的命令有兩個：<code>top</code> 和 <code>ps</code> 命令。<code>top</code> 是每個系統管理員都知道的工具，用 <code>top</code> 命令，你能夠知道到所有當前正在運行的進程有哪些。在命令列裏，輸入 <code>top</code> 命令能夠就看到你正在運行的程序進程（圖1）</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/killa.jpg?itok=95cUI9Lh" alt="top" title="top"></p><p><em>圖 1： top 命令給出你許多的信息。</em></p><p>從顯示的列表中你能夠看到相當重要的信息，舉個例子，Chrome 瀏覽器反映遲鈍，依據我們的 <code>top</code> 命令顯示，我們能夠辨別的有四個 Chrome 瀏覽器的進程在運行，進程的 pid 號分別是 3827、3919、10764 和 11679。這個信息是重要的，可以用一個特殊的方法來結束進程。</p><p>儘管 <code>top</code> 命令很是方便，但也不是得到你所要信息最有效的方法。 你知道你要殺死的 Chrome 進程是那個，並且你也不想看 <code>top</code> 命令所顯示的實時信息。 鑑於此，你能夠使用 <code>ps</code> 命令然後用 <code>grep</code> 命令來過濾出輸出結果。這個 <code>ps</code> 命令能夠顯示出當前進程列表的快照，然後用 <code>grep</code> 命令輸出匹配的樣式。我們通過 <code>grep</code> 命令過濾 <code>ps</code> 命令的輸出的理由很簡單：如果你只輸入 <code>ps</code> 命令，你將會得到當前所有進程的列表快照，而我們需要的是列出 Chrome 瀏覽器進程相關的。所以這個命令是這個樣子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps aux | grep chrome</span></span></code></pre></div><p>這裏 <code>aux</code> 選項如下所示：</p><ul><li>a = 顯示所有用户的進程</li><li>u = 顯示進程的用户和擁有者</li><li>x = 也顯示不依附於終端的進程</li></ul><p>當你搜索圖形化程序的信息時，這個 <code>x</code> 參數是很重要的。</p><p>當你輸入以上命令的時候，你將會得到比圖 2 更多的信息，而且它有時用起來比 <code>top</code> 命令更有效。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/killb.jpg?itok=vyWIuTva" alt="ps command" title="ps command"></p><p><em>圖 2：用 ps 命令來定位所需的內容信息。</em></p><h3 id="結束進程" tabindex="-1">結束進程 <a class="header-anchor" href="#結束進程" aria-label="Permalink to “結束進程”">​</a></h3><p>現在我們開始結束進程的任務。我們有兩種可以幫我們殺死錯誤的進程的信息。</p><ul><li>進程的名字</li><li>進程的 ID （PID）</li></ul><p>你用哪一個將會決定終端命令如何使用，通常有兩個命令來結束進程：</p><ul><li><code>kill</code> - 通過進程 ID 來結束進程</li><li><code>killall</code> - 通過進程名字來結束進程</li></ul><p>有兩個不同的信號能夠發送給這兩個結束進程的命令。你發送的信號決定着你想要從結束進程命令中得到的結果。舉個例子，你可以發送 <code>HUP</code>（掛起）信號給結束進程的命令，命令實際上將會重啓這個進程。當你需要立即重啓一個進程（比如就守護進程來説），這是一個明智的選擇。你通過輸入 <code>kill -l</code> 可以得到所有信號的列表，你將會發現大量的信號。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/killc.jpg?itok=9ewRHFW2" alt=""></p><p><em>圖 3： 可用的結束進程信號。</em></p><p>最經常使用的結束進程的信號是：</p><div class="table-wrap"><table><thead><tr><th>Signal Name</th><th>Single Value</th><th>Effect</th></tr></thead><tbody><tr><td>SIGHUP</td><td>1</td><td>掛起</td></tr><tr><td>SIGINT</td><td>2</td><td>鍵盤的中斷信號</td></tr><tr><td>SIGKILL</td><td>9</td><td>發出殺死信號</td></tr><tr><td>SIGTERM</td><td>15</td><td>發出終止信號</td></tr><tr><td>SIGSTOP</td><td>17, 19, 23</td><td>停止進程</td></tr></tbody></table></div><p>好的是，你能用信號值來代替信號名字。所以你沒有必要來記住所有各種各樣的信號名字。</p><p>所以，讓我們現在用 <code>kill</code> 命令來殺死 Chrome 瀏覽器的進程。這個命令的結構是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kill SIGNAL PID</span></span></code></pre></div><p>這裏 SIGNAL 是要發送的信號，PID 是被殺死的進程的 ID。我們已經知道，來自我們的 <code>ps</code> 命令顯示我們想要結束的進程 ID 號是 3827、3919、10764 和 11679。所以要發送結束進程信號，我們輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>kill -9 3827</span></span>
<span class="line"><span>kill -9 3919</span></span>
<span class="line"><span>kill -9 10764</span></span>
<span class="line"><span>kill -9 11679</span></span></code></pre></div><p>一旦我們輸入了以上命令，Chrome 瀏覽器的所有進程將會成功被殺死。</p><p>我們有更簡單的方法！如果我們已經知道我們想要殺死的那個進程的名字，我們能夠利用 <code>killall</code> 命令發送同樣的信號，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>killall -9 chrome</span></span></code></pre></div><p>附帶説明的是，上邊這個命令可能不能捕捉到所有正在運行的 Chrome 進程。如果，運行了上邊這個命令之後，你輸入 <code>ps aux | grep chrome</code> 命令過濾一下，看到剩下正在運行的 Chrome 進程有那些，最好的辦法還是回到 <code>kIll</code> 命令通過進程 ID 來發送信號值 <code>9</code> 來結束這個進程。</p><h3 id="結束進程很容易" tabindex="-1">結束進程很容易 <a class="header-anchor" href="#結束進程很容易" aria-label="Permalink to “結束進程很容易”">​</a></h3><p>正如你看到的，殺死錯誤的進程並沒有你原本想的那樣有挑戰性。當我讓一個頑固的進程結束的時候，我趨向於用 <code>killall</code>命令來作為有效的方法來終止，然而，當我讓一個真正的活躍的進程結束的時候，<code>kill</code>命令是一個好的方法。</p><hr>`,42)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(l,{href:"https://www.linux.com/learn/intro-to-linux/2017/5/how-kill-process-command-line"},{default:s(()=>[...e[0]||(e[0]=[t("https://www.linux.com/learn/intro-to-linux/2017/5/how-kill-process-command-line",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),i(l,{href:"https://www.linux.com/users/jlwallen"},{default:s(()=>[...e[2]||(e[2]=[t("JACK WALLEN",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),i(l,{href:"https://github.com/hwlog"},{default:s(()=>[...e[3]||(e[3]=[t("hwlog",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:s(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:s(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const w=a(c,[["render",h]]);export{C as __pageData,w as default};
